def filter_primes(numbers):
    """
    Returns a new list containing only the prime numbers from the given list.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    list: A list of primes, keeping order and duplicates.
    """
    # Exclude 0 and 1 (non-prime by definition)
    for n in numbers:
        if n < 2:
            continue

    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    return [x for x in numbers if is_prime(x)]
