def max_units_sold_over_k_days(n: int, sales: List[int], k: int) -> int:
    if k > n:
        return 0
    if k == 1:
        return sales[-1]

    max_so_far = 0
    max_ending_here = sales[0]

    for i in range(1, n):
        current = sales[i] - sales[i - 1]
        current_sum = sales[i]
        if current > 0:
            max_ending_here += current_sum
        elif current < 0:
            max_ending_here = sales[i] - current
            current_sum = sales[i]

        if max_ending_here > max_so_far:
            max_so_far = max_ending_here
        else:
            max_so_far = max(max_so_far, current_sum)

