def smallest_lexicographic_substring(s: str, k: int) -> str:
    if len(s) < k or k < 1:
        return ""
    # Count occurrences of each character
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1

    # Sort keys lexicographically
    chars = sorted(counts.keys())

    if not chars:
        return ""

    # Build a list of substrings of length k
    substrings = []
    for char_idx, char in enumerate(chars):
        length = k - char_idx
        if length > len(s) or (length == 0 and char_idx >= len(s)):
            continue
        substring = s[char_idx : char_idx + length]
        substrings.append(substring)

    if not substrings:
        return ""

    # The first one found is the smallest lexicographically
    return substrings[0]
