    Return a new string from s such that each character appears exactly once
    in the order it appears in s. If a character appears multiple times,
    only the first occurrence is kept; later occurrences are ignored.

    For empty string s, return an empty string "".
    """
    if not s:
        return ""

    # Dictionary to map character -> first occurrence index
    char_map = {}
    for i, c in enumerate(s):
        if c not in char_map:
            char_map[c] = i

    # Collect characters from first occurrence index to the end
    result = []
    for c in s:
        if c in char_map:
            result.append(char_map[c])

    # Join the collected indices in order
    return ''.join(map(chr, result))
