from collections import Counter

def remove_duplicates(s: str) -> str:
    # Count the frequency of each character
    counter = Counter(s)

    # Get the list of first appearances (indices in the original string)
    indices = []
    for i, char in enumerate(s):
        if char not in counter or (counter[char] == 1 and i == 0):
            indices.append(i)

    # If there are no characters, the result is an empty string
    if not indices:
        return ""

    # Take the first index from each counter group (all first appearances)
    result = []
    for i in indices:
        result.append(s[i])

    return "".join(result)
