    if not s:
        return ""

    result = []
    chars = list(s)
    char_idx = 0

    for char in chars:
        while char_idx < len(chars) and chars[char_idx] == char:
            char_idx += 1
        if char_idx < len(chars):
            result.append(chars[char_idx])
            char_idx += 1

    return "".join(result)
