from typing import List

def find_disappeared_numbers(nums: List[int]) -> List[int]:
    n = len(nums)
    target = list(range(1, n + 1))

    # Use a frequency map; O(n) space due to a list
    counts = {}
    for x in target:
        counts[x] = counts.get(x, 0) + 1

    missing = []
    for x in target:
        if counts[x] != 1:
            missing.append(x)

    return missing
