def bfs_shortest_path(graph, start, end):
    """
    Find the shortest path length (in terms of number of edges) between
    start and end nodes in an undirected graph. Returns -1 if no path exists.

    Parameters:
        graph (dict): Adjacency list representation of the graph
        start (int): Starting node index
        end (int): Target node index

    Returns:
        int: Shortest path length or -1 if unreachable
    """
    # Normalize node indices to 0-based
    nodes = [node for node in graph]
    idx = {node: i for i, node in enumerate(nodes)}

    visited = set()

    def dfs(u, p=None):
        """Depth-first search to find the shortest path between start and end."""
        nonlocal visited
        visited.add(u)
        p = p if p else {u: {} if u != start else None}

        for v in graph[u]:
            if v == end:
                return u
            if v not in visited:
                result = dfs(v, p)
                if result is not None:
                    return result
            elif v != start and v not in visited:
                visited.add(v)
                result = dfs(v, p)
                if result is not None:
                    return result
            elif v != start and p[u] == u:
                # Found path to start through v; backtrack
                p[v] = None

    return dfs(start)
```

