def concatenate_k_lexicographically(words, k):
    """
    Given a list of `n` unique strings (words), sort them lexicographically and
    return the concatenation of the first `k` words.

    Raises ValueError if k > len(words).
    Raises ValueError if k < 0.
    """
    if not isinstance(words, list):
        raise TypeError("words must be a list")
    if not isinstance(k, int):
        raise TypeError("k must be an integer")

    if k < 0 or k > len(words):
        raise ValueError("k must be between 0 and the length of words")
    if k == 0:
        return ""

    words.sort()
    return "".join(words[:k])
```

