    for t in time_limit:
        if t <= 5000:
            max_memory_used = max(max_memory_used, t)
        else:
            break

    if max_memory_used <= 100000000:  # 100 MB is a reasonable limit
        for execution_time in execution_times:
            if execution_time > time_limit:
                print("Disqualified")
            else:
                print("Accepted")
    else:
        print("Disqualified")
